import { Plugin } from '../plugin';
import { parseContent } from '../parse';

export const markdownPlugin: Plugin = {
  name: 'markdown',
  onFile(page) {
    return parseContent(page.content, page.slug);
  },
};

import fs from 'fs';
import path from 'path';
import { Plugin } from '../plugin';
import { createTemplateEngine, TemplateEngine } from '../templates';
import { renderIndex, renderPage } from '../render';

function resolveTemplatesDir(contentDir: string, templatesDir?: string): string {
  return templatesDir ?? path.join(path.dirname(contentDir), 'templates');
}

export function createTemplatePlugin(): Plugin {
  let engine: TemplateEngine | null = null;

  return {
    name: 'template',
    beforeBuild(ctx) {
      const dir = resolveTemplatesDir(ctx.options.contentDir, ctx.options.templatesDir);
      engine = fs.existsSync(dir) ? createTemplateEngine(dir) : null;
    },
    onFile(page) {
      const html = engine ? (engine.renderPage(page) ?? renderPage(page)) : renderPage(page);
      return { ...page, html };
    },
    afterBuild(ctx) {
      const index = engine
        ? (engine.renderIndex(ctx.pages) ?? renderIndex(ctx.pages))
        : renderIndex(ctx.pages);
      ctx.writeFile('index.html', index);
    },
  };
}

import http from 'http';
import fs from 'fs';
import path from 'path';
import chokidar, { FSWatcher } from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { Plugin, PluginContext } from '../plugin';

export interface DevServerOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  host?: string;
  port?: number;
}

export interface DevServer {
  server: http.Server;
  wss: WebSocketServer;
  watcher: FSWatcher;
  ready: Promise<void>;
  close(): Promise<void>;
}

interface InternalDevServer extends DevServer {
  broadcast(message: unknown): void;
}

export interface DevServerPluginOptions {
  host?: string;
  port?: number;
}

export interface DevServerPluginInstance {
  plugin: Plugin;
  getDevServer(): DevServer;
}

const REBUILD_DEBOUNCE_MS = 100;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.mjs': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.webp': 'image/webp',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.txt': 'text/plain; charset=utf-8',
};

export function liveReloadScript(): string {
  return `<script>
(function () {
  var scheme = location.protocol === 'https:' ? 'wss:' : 'ws:';
  var socket = new WebSocket(scheme + '//' + location.host);
  socket.addEventListener('message', function (event) {
    var data;
    try {
      data = JSON.parse(event.data);
    } catch (err) {
      return;
    }
    if (data && data.type === 'reload') {
      location.reload();
    }
  });
  socket.addEventListener('close', function () {
    setTimeout(function () {
      location.reload();
    }, 2000);
  });
})();
</script>`;
}

export function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  const idx = html.lastIndexOf('</body>');
  if (idx === -1) {
    return html + script;
  }
  return html.slice(0, idx) + script + html.slice(idx);
}

function createHandler(outputDir: string): http.RequestListener {
  const root = path.resolve(outputDir);
  return (req, res) => {
    const urlPath = (req.url ?? '/').split('?')[0];
    const rel = urlPath === '/' ? 'index.html' : urlPath.replace(/^\/+/, '');
    const filePath = path.resolve(root, rel);

    if (filePath !== root && !filePath.startsWith(root + path.sep)) {
      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Forbidden');
      return;
    }

    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
        res.end('Not Found');
        return;
      }
      const type = MIME_TYPES[path.extname(filePath).toLowerCase()] ?? 'application/octet-stream';
      const body = filePath.endsWith('.html')
        ? injectLiveReload(data.toString('utf-8'))
        : data;
      res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-cache' });
      res.end(body);
    });
  };
}

function startServer(ctx: PluginContext, opts: DevServerPluginOptions): InternalDevServer {
  const { options } = ctx;
  const host = opts.host ?? 'localhost';
  const port = opts.port ?? 3000;

  const server = http.createServer(createHandler(options.outputDir));
  const wss = new WebSocketServer({ server });
  let timer: NodeJS.Timeout | null = null;
  let closed = false;
  let watcher: FSWatcher;

  const broadcast = (message: unknown): void => {
    const payload = JSON.stringify(message);
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send(payload);
      }
    }
  };

  const rebuild = (): void => {
    if (closed) return;
    try {
      const pages = ctx.engine.build();
      console.log(`Rebuilt ${pages.length} page${pages.length === 1 ? '' : 's'}`);
    } catch (err) {
      console.error(`Build failed: ${(err as Error).message}`);
    }
  };

  const templatesDir = options.templatesDir;
  const watchDirs = templatesDir ? [options.contentDir, templatesDir] : [options.contentDir];
  watcher = chokidar.watch(watchDirs, { ignoreInitial: true });

  const ready = new Promise<void>((resolve) => watcher.on('ready', () => resolve()));

  const schedule = (): void => {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      rebuild();
    }, REBUILD_DEBOUNCE_MS);
  };

  watcher
    .on('add', schedule)
    .on('change', schedule)
    .on('unlink', schedule)
    .on('addDir', schedule)
    .on('unlinkDir', schedule);

  server.listen(port, host);

  const close = async (): Promise<void> => {
    closed = true;
    if (timer) {
      clearTimeout(timer);
      timer = null;
    }
    await watcher.close();
    for (const client of wss.clients) {
      client.close();
    }
    await new Promise<void>((resolve) => wss.close(() => resolve()));
    await new Promise<void>((resolve) => server.close(() => resolve()));
  };

  return { server, wss, watcher, ready, close, broadcast };
}

export function createDevServerPlugin(opts: DevServerPluginOptions): DevServerPluginInstance {
  let dev: InternalDevServer | null = null;

  const plugin: Plugin = {
    name: 'dev-server',
    onStart(ctx) {
      dev = startServer(ctx, opts);
    },
    afterBuild() {
      if (dev) dev.broadcast({ type: 'reload', timestamp: Date.now() });
    },
  };

  return {
    plugin,
    getDevServer(): DevServer {
      if (!dev) {
        throw new Error('Dev server plugin has not started');
      }
      return dev;
    },
  };
}

import { Plugin } from '../plugin';
import { markdownPlugin } from './markdown';
import { createTemplatePlugin } from './template';

export { markdownPlugin } from './markdown';
export { createTemplatePlugin } from './template';
export {
  createDevServerPlugin,
  liveReloadScript,
  injectLiveReload,
} from './dev-server';
export type {
  DevServer,
  DevServerOptions,
  DevServerPluginInstance,
} from './dev-server';

export function builtinPlugins(): Plugin[] {
  return [markdownPlugin, createTemplatePlugin()];
}

import fs from 'fs';
import path from 'path';
import { Page, BuildOptions } from './types';
import { Plugin, PluginContext, PluginPipeline } from './plugin';
import { collectMarkdownFiles } from './collect';
import { slugify } from './parse';

export interface SSGOptions {
  options: BuildOptions;
  plugins: Plugin[];
}

export class SSG {
  readonly options: BuildOptions;
  private pipeline: PluginPipeline;
  private ctx: PluginContext;
  private started = false;

  constructor(opts: SSGOptions) {
    this.options = opts.options;
    this.pipeline = new PluginPipeline(opts.plugins);
    this.ctx = {
      engine: this,
      options: this.options,
      pages: [],
      writeFile: (relPath, content) => {
        const out = path.join(this.options.outputDir, relPath);
        fs.mkdirSync(path.dirname(out), { recursive: true });
        fs.writeFileSync(out, content, 'utf-8');
      },
    };
  }

  get plugins(): Plugin[] {
    return this.pipeline.plugins;
  }

  start(): this {
    if (this.started) return this;
    this.started = true;
    this.pipeline.run('onStart', this.ctx);
    return this;
  }

  build(): Page[] {
    fs.rmSync(this.options.outputDir, { recursive: true, force: true });
    fs.mkdirSync(this.options.outputDir, { recursive: true });

    this.ctx.pages = [];
    this.pipeline.run('beforeBuild', this.ctx);

    for (const file of collectMarkdownFiles(this.options.contentDir)) {
      this.ctx.currentFile = file;
      const raw = fs.readFileSync(file, 'utf-8');
      const page: Page = { slug: slugify(file), content: raw, html: '', data: {} };
      const result = this.pipeline.runFile(page, this.ctx);
      this.ctx.pages.push(result);
      this.ctx.writeFile(`${result.slug}.html`, result.html);
    }

    this.pipeline.run('afterBuild', this.ctx);
    this.pipeline.run('onEnd', this.ctx);
    return this.ctx.pages;
  }
}

export function createSSG(options: SSGOptions): SSG {
  return new SSG(options);
}

import { Page, BuildOptions } from './types';
import { SSG } from './engine';
import { builtinPlugins } from './plugins';

export { collectPages } from './collect';

export function buildSite(options: BuildOptions): Page[] {
  const engine = new SSG({ options, plugins: builtinPlugins() });
  engine.start();
  return engine.build();
}

import { SSG } from './engine';
import { builtinPlugins, createDevServerPlugin } from './plugins';

export { liveReloadScript, injectLiveReload } from './plugins/dev-server';
export type { DevServer, DevServerOptions } from './plugins/dev-server';

export function startDevServer(options: DevServerOptions): DevServer {
  const dev = createDevServerPlugin({ host: options.host, port: options.port });
  const engine = new SSG({
    options: {
      contentDir: options.contentDir,
      outputDir: options.outputDir,
      templatesDir: options.templatesDir,
    },
    plugins: [...builtinPlugins(), dev.plugin],
  });
  engine.start();

  try {
    const pages = engine.build();
    console.log(`Built ${pages.length} page${pages.length === 1 ? '' : 's'} into ${options.outputDir}`);
  } catch (err) {
    console.error(`Initial build failed: ${(err as Error).message}`);
  }

  return dev.getDevServer();
}

import fs from 'fs';
import path from 'path';
import { Plugin } from './plugin';
import { builtinPlugins } from './plugins';

export interface SSGConfig {
  plugins: Plugin[];
}

export const DEFAULT_CONFIG_FILE = 'ssg.config.ts';

export function resolveConfigPath(configPath?: string): string {
  return configPath
    ? path.resolve(process.cwd(), configPath)
    : path.resolve(process.cwd(), DEFAULT_CONFIG_FILE);
}

export function loadConfig(configPath?: string): SSGConfig {
  const resolved = resolveConfigPath(configPath);
  if (!fs.existsSync(resolved)) {
    return { plugins: builtinPlugins() };
  }
  try {
    const mod = require(resolved);
    const exported = (mod && mod.default) ?? mod;
    const cfg = typeof exported === 'function' ? exported() : exported;
    if (cfg && Array.isArray(cfg.plugins) && cfg.plugins.length > 0) {
      return cfg as SSGConfig;
    }
    return { plugins: builtinPlugins() };
  } catch {
    return { plugins: builtinPlugins() };
  }
}

import { builtinPlugins } from './src/plugins';
import { Plugin } from './src/plugin';

export const plugins: Plugin[] = builtinPlugins();

export default { plugins };

